import { Component, TemplateRef, forwardRef, input } from '@angular/core';
import { FormsModule, NG_VALUE_ACCESSOR } from '@angular/forms';
import { NzCalendarModule } from 'ng-zorro-antd/calendar';
import { HrmControl } from '../shared/hrm-control';

/** Ô ngày/tháng nhận `$implicit: Date` — dùng cho dateCell/monthCell tuỳ biến. */
export type HrmCalendarCell = TemplateRef<{ $implicit: Date }>;

/** hrm-calendar — lịch, CVA Date. Cần registerLocaleData(vi).
 *  - fullscreen=false = mini (thu gọn, nhúng trong card/popover).
 *  - mode 'month' | 'year' — lưới ngày trong tháng hoặc lưới tháng trong năm.
 *  - dateCell/monthCell: TemplateRef nhận `$implicit: Date` để vẽ nội dung tuỳ biến
 *    trong từng ô (badge sự kiện, dấu ngày nghỉ/lễ...). */
@Component({
  selector: 'hrm-calendar',
  imports: [FormsModule, NzCalendarModule],
  template: `
    <nz-calendar
      [ngModel]="value()"
      (ngModelChange)="emit($event)"
      [nzMode]="mode()"
      [nzFullscreen]="fullscreen()"
      [nzDateCell]="dateCell() ?? undefined"
      [nzMonthCell]="monthCell() ?? undefined"></nz-calendar>
  `,
  host: { class: 'hrm-calendar' },
  providers: [{ provide: NG_VALUE_ACCESSOR, useExisting: forwardRef(() => HrmCalendar), multi: true }],
})
export class HrmCalendar extends HrmControl<Date> {
  readonly fullscreen = input(false);
  readonly mode = input<'month' | 'year'>('month');
  readonly dateCell = input<HrmCalendarCell | null>(null);
  readonly monthCell = input<HrmCalendarCell | null>(null);
}
